import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface LoginRequest { email: string; password: string; }
export interface LoginResponse { token: string; user: { id: string; email: string; role: 'driver' | 'admin'; }; }

@Injectable({ providedIn: 'root' })
export class AuthService {
  private http = inject(HttpClient);

  login(req: LoginRequest): Observable<LoginResponse> {
    return this.http.post<LoginResponse>('/auth/login', req);
  }
}

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Zone { id: string; name: string; rate_per_hour: number; currency: string; }
export interface NearbyZoneResponse { in_zone: boolean; zone: Zone | null; }

@Injectable({ providedIn: 'root' })
export class ZoneService {
  private http = inject(HttpClient);

  getNearbyZone(latitude: number, longitude: number): Observable<NearbyZoneResponse> {
    return this.http.get<NearbyZoneResponse>('/zones/nearby', { params: { latitude: String(latitude), longitude: String(longitude) } });
  }
}

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Session { id: string; zone_id: string; zone_name: string; started_at: string; rate_per_hour: number; currency: string; status: 'active' | 'completed' | 'overdue'; current_amount?: number; ended_at?: string; duration_seconds?: number; amount?: number; }

@Injectable({ providedIn: 'root' })
export class SessionService {
  private http = inject(HttpClient);

  startSession(zoneId: string, latitude?: number, longitude?: number): Observable<{ session: Session; payment: { id: string; amount: number; status: 'pending'; } }> {
    return this.http.post<any>('/sessions', { zone_id: zoneId, latitude, longitude });
  }

  getActiveSession(): Observable<{ session: Session | null }> {
    return this.http.get<{ session: Session | null }>('/sessions/active');
  }

  endSession(sessionId: string): Observable<{ session: Session; payment: { id: string; amount: number; status: 'paid'; paid_at: string; } }> {
    return this.http.post<any>(`/sessions/${sessionId}/end`, {});
  }
}

import { Component, inject } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({ selector: 'app-login', template: `<div *ngIf="loading">Загрузка...</div><div *ngIf="error">{{ error }}</div><form [formGroup]="form" (ngSubmit)="submit()"><input formControlName="email" placeholder="Email" /><input formControlName="password" type="password" placeholder="Пароль" /><button type="submit" [disabled]="loading || !form.valid">Войти</button></form>` })
export class LoginComponent {
  private fb = inject(FormBuilder);
  private auth = inject(AuthService);
  private router = inject(Router);
  form: FormGroup = this.fb.group({ email: ['', [Validators.required, Validators.email]], password: ['', Validators.required] });
  loading = false;
  error = '';

  submit() {
    if (!this.form.valid) return;
    this.loading = true;
    this.error = '';
    this.auth.login(this.form.value).subscribe({
      next: (res) => { localStorage.setItem('token', res.token); this.router.navigate(['/']); },
      error: (err) => { this.error = 'Неверные данные'; this.loading = false; }
    });
  }
}

import { Component, inject, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { ZoneService, NearbyZoneResponse } from '../../services/zone.service';
import { SessionService } from '../../services/session.service';

@Component({ selector: 'app-home', template: `<div *ngIf="loading">Определение зоны...</div><div *ngIf="error">{{ error }}</div><div *ngIf="!loading && !error"><div *ngIf="!zone">Вне платной зоны</div><div *ngIf="zone"><h2>{{ zone.name }}</h2><p>Тариф: {{ zone.rate_per_hour }} {{ zone.currency }}/час</p><button (click)="startSession()">Начать сессию</button></div><button (click)="router.navigate(['/history'])">История</button><button (click)="router.navigate(['/notifications'])">Уведомления</button></div>` })
export class HomeComponent implements OnInit {
  private zoneService = inject(ZoneService);
  private sessionService = inject(SessionService);
  private router = inject(Router);
  loading = true;
  error = '';
  zone: NearbyZoneResponse['zone'] = null;

  ngOnInit() { this.detectZone(); }

  detectZone() {
    this.loading = true;
    this.error = '';
    navigator.geolocation.getCurrentPosition(
      (pos) => this.zoneService.getNearbyZone(pos.coords.latitude, pos.coords.longitude).subscribe({
        next: (res) => { this.zone = res.zone; this.loading = false; },
        error: () => { this.error = 'Ошибка определения зоны'; this.loading = false; }
      }),
      () => { this.error = 'Ошибка геолокации'; this.loading = false; }
    );
  }

  startSession() {
    if (!this.zone) return;
    this.sessionService.startSession(this.zone.id).subscribe({
      next: () => this.router.navigate(['/session']),
      error: () => this.error = 'Не удалось начать сессию'
    });
  }
}
